require 'fluent/plugin/output'
require 'fluent/plugin_helper/socket'
require 'fluent/engine'
require 'fluent/clock'
require 'fluent/plugin/out_forward/connection_manager'

module Fluent::Plugin
  class ForwardOutput < Output
    class AckHandler
      module Result
        SUCCESS = :success
        FAILED = :failed
        CHUNKID_UNMATCHED = :chunkid_unmatched
      end

      attr_reader :read_length, :unpacker

      def initialize(timeout:, log:, read_length:, connection_manager: nil)
        @mutex = Mutex.new
        @ack_waitings = []
        @timeout = timeout
        @log = log
        @read_length = read_length
        @unpacker = Fluent::MessagePackFactory.msgpack_unpacker
        @connection_manager = connection_manager || ConnectionManager.new(log: log, secure: false, connection_factory: nil, socket_cache: nil)
      end

